// AUTHORED PAPER CORPUS FOR THE LONG HALL / HAYSTACK.
//
// The horror here is unstable authorship, not increasingly damaged typography.
// Every entry below is a finished sheet. Runtime code may choose a sheet because
// of exposure or a lived semantic fact, but it never assembles sentences.
//
// `body` is an AST for document structure only. It never carries speaker
// identity: handwriting, case, colour, and layout are not a Surfer channel.

const freeze = (value) => Object.freeze(value);
export const line = (text) => freeze({ type: 'line', text: String(text) });
export const field = (label, value) => freeze({ type: 'field', label: String(label), value: String(value) });
export const gap = () => freeze({ type: 'gap' });

function renderBody(body = []) {
  return body.map((node) => {
    if (node.type === 'field') return `${node.label}: ${node.value}`;
    if (node.type === 'gap') return '';
    return node.text || '';
  });
}

function note(def) {
  const body = freeze([...(def.body || [])]);
  const page = {
    ...def,
    body,
    lines: freeze(renderBody(body)),
    techniques: freeze([...(def.techniques || [])]),
    requiresFacts: freeze([...(def.requiresFacts || [])]),
    excludesFacts: freeze([...(def.excludesFacts || [])]),
    stage: Math.max(0, Math.min(4, Math.floor(Number(def.hallMin) || 0))),
  };
  return freeze(page);
}

