export function sourcePageById(id) {
  return SOURCE_PAGES.find((page) => page.id === id) || null;
}

// Compatibility selector for probes and older tests. Gameplay uses the dialogue
// director, which adds exposure, history, fact gating, and immutable assignment.
export function sourcePageFor(index = 0, hallStage = 0, seed = 0) {
  const stage = Math.max(0, Math.min(4, Math.floor(Number(hallStage) || 0)));
  const pool = SOURCE_PAGES.filter((page) => page.hallMin <= stage && page.stage <= stage);
  const eligible = pool.length ? pool : SOURCE_PAGES;
  let x = ((Math.abs(Math.floor(index)) + 1) * 2654435761) ^ ((Math.abs(Math.floor(seed)) + 1) * 40503);
  x ^= x >>> 16; x = Math.imul(x, 0x7feb352d); x ^= x >>> 15; x = Math.imul(x, 0x846ca68b); x ^= x >>> 16;
  return eligible[(x >>> 0) % eligible.length];
}

export function sourcePageLines(page) {
  return page?.lines ? [...page.lines] : [];
}

const SOURCE_PAPER_PROFILE = Object.freeze({
  0: 'handledCopy',
  1: 'handledCopy',
  2: 'badPhotocopy',
  3: 'badPhotocopy',
  4: 'damagedCopy',
});

// Source pages are ordinary Ellery paperwork whose CONTENT is failing. They use
// the same physical-paper reader as every other found sheet; the transport
// corruption above is already authored, so do not add document.js erosion on top.
export function sourcePageDocument(sourcePage) {
  if (!sourcePage) return null;
  const [title = 'FOUND DOCUMENT', ...body] = Array.isArray(sourcePage.lines) ? sourcePage.lines : [];
  const stage = Math.max(0, Math.min(4, Math.floor(Number(sourcePage.stage) || 0)));
  return Object.freeze({
    id: `source-page:${sourcePage.id}`,
    title,
    byline: 'W. ELLERY / WORKS',
    decay: 0,
    body: Object.freeze(body.map((line) => Object.freeze({ raw: String(line) }))),
    paper: Object.freeze({
      profile: SOURCE_PAPER_PROFILE[stage],
      issuer: 'ellery-works',
      template: sourcePage.register || 'freeform',
      reproduction: ['original-handled','copy-g1','copy-g2','copy-g4','copy-g8'][stage],
    }),
    sourcePageId: sourcePage.id,
    sourceRegister: sourcePage.register || null,
    sourceStage: stage,
  });
}
